<?php
/**
 * QuickCart_DemoData
 */
declare(strict_types=1);

namespace QuickCart\DemoData\Setup\Patch\Data;

use Magento\Framework\Setup\Patch\DataPatchInterface;
use Magento\Framework\Stdlib\DateTime\TimezoneInterface;
use QuickCart\SalesDashboard\Api\SalesTargetRepositoryInterface;
use QuickCart\SalesDashboard\Model\SalesTargetFactory;

/**
 * Monthly sales targets from four months ago to next month (relative to the install
 * date), sized for the demo order history generated by quickcart:demo:orders.
 */
class InstallSalesTargets implements DataPatchInterface
{
    /**
     * Month offset => [revenue target (INR), orders target, note].
     */
    private const TARGETS = [
        -4 => [600000, 20, 'Launch month'],
        -3 => [800000, 30, null],
        -2 => [950000, 30, 'Festive season build-up'],
        -1 => [1100000, 35, 'Diwali sale month'],
        0 => [1300000, 45, 'Wedding season + year-end deals'],
        1 => [1500000, 50, 'Holiday gifting'],
    ];

    /**
     * @param SalesTargetFactory $targetFactory
     * @param SalesTargetRepositoryInterface $repository
     * @param TimezoneInterface $timezone
     */
    public function __construct(
        private readonly SalesTargetFactory $targetFactory,
        private readonly SalesTargetRepositoryInterface $repository,
        private readonly TimezoneInterface $timezone
    ) {
    }

    /**
     * @inheritdoc
     */
    public function apply(): self
    {
        $month = \DateTimeImmutable::createFromMutable($this->timezone->date())->modify('first day of this month');
        foreach (self::TARGETS as $offset => [$revenue, $orders, $note]) {
            $period = $month->modify(sprintf('%+d months', $offset))->format('Y-m');
            if ($this->repository->getByPeriod($period)) {
                continue;
            }
            $target = $this->targetFactory->create();
            $target->setPeriod($period)
                ->setRevenueTarget((float)$revenue)
                ->setOrdersTarget($orders)
                ->setNote($note);
            $this->repository->save($target);
        }

        return $this;
    }

    /**
     * @inheritdoc
     */
    public static function getDependencies(): array
    {
        return [];
    }

    /**
     * @inheritdoc
     */
    public function getAliases(): array
    {
        return [];
    }
}
